{"tool": "writeProjectFile", "params": {"content": "import { AttackerProfile, ProfileMutation } from './profile';
import { readFileSync, writeFileSync, renameSync, existsSync } from 'fs';

export class ProfileStore {
  private nextSeqCounter: number = 0;
  private lastAppliedSeqCounter: number = 0;

  constructor(private logPath: string, private snapshotPath: string) {}

  apply(mutation: ProfileMutation, profile: AttackerProfile): void {
    mutation.seq = ++this.nextSeqCounter;
    profile.recent.push(mutation);
    this.lastAppliedSeqCounter = mutation.seq;
  }

  load(): AttackerProfile[] {
    let profiles: AttackerProfile[] = [];
    if (existsSync(this.snapshotPath)) {
      const raw = readFileSync(this.snapshotPath, 'utf8');
      let parsed: { schema?: number; nextSeq?: number; lastAppliedSeq?: number; profiles?: AttackerProfile[] };
      try { 
        parsed = JSON.parse(raw); 
      } catch { return []; }

      profiles = parsed.profiles || [];
      if (parsed.schema === 2) {
        this.nextSeqCounter = parsed.nextSeq || 0;
        this.lastAppliedSeqCounter = parsed.lastAppliedSeq || 0;
      }
    }

    if (existsSync(this.logPath)) {
      const log = readFileSync(this.logPath, 'utf8').split('\n').filter(Boolean);
      for (const entry of log) {
        const m: ProfileMutation = JSON.parse(entry);
        if (m.seq !== undefined && m.seq <= this.lastAppliedSeqCounter) continue;

        const target = profiles.find(p => p.id === m.id) || { id: m.id, recent: [] };
        if (!profiles.includes(target)) profiles.push(target);
        target.recent.push(m);
        if (m.seq) this.lastAppliedSeqCounter = Math.max(this.lastAppliedSeqCounter, m.seq);
      }
    }
    return profiles;
  }

  snapshot(profiles: AttackerProfile[]): void {
    const data = {
      schema: 2,
      nextSeq: this.nextSeqCounter,
      lastAppliedSeq: this.lastAppliedSeqCounter,
      profiles
    };
    const tmp = `${this.snapshotPath}.tmp`;
    writeFileSync(tmp, JSON.stringify(data));
    renameSync(tmp, this.snapshotPath);
    writeFileSync(this.logPath, '');
  }

  setCounters(next: number, last: number) {
    this.nextSeqCounter = next;
    this.lastAppliedSeqCounter = last;
  }
}", "path": "src/ai/hunt-mode/profile-store.ts"}}
